<?php
declare(strict_types=1);
require_once __DIR__.'/includes/init.php';require_once __DIR__.'/csrf_helper.php';require_once __DIR__.'/includes/shop_assisted_sale.php';
staffRequireActivePosition('order_operator');
function assistedH(mixed $v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
$error='';$result=null;
$_SESSION['assisted_request']??=['key'=>bin2hex(random_bytes(16)),'access'=>bin2hex(random_bytes(32))];
if($_SERVER['REQUEST_METHOD']==='POST'){
 try{
  if(!csrf_verify((string)($_POST['csrf_token']??'')))throw new InvalidArgumentException('Formulář vypršel.');
  if(!hash_equals($_SESSION['assisted_request']['key'],(string)($_POST['request_key']??'')))throw new InvalidArgumentException('Otevřete původní objednávku nebo nový prodej.');
  $result=shopAssistedSalePlace($pdo,(int)($_POST['variant_id']??0),(int)($_POST['quantity']??0),$_POST,(int)$_SESSION['trener_id'],(string)($_POST['reason']??''),$_SESSION['assisted_request']['key'],$_SESSION['assisted_request']['access'],shopBankSettingsFromConfig(),(int)($_POST['account_id']??0)?:null,(int)($_POST['beneficiary_id']??0)?:null,(string)($_POST['payer_name']??''),(string)($_POST['recipient_name']??''));
  $_SESSION['assisted_last_order']=['id'=>(int)$result['id'],'code'=>$result['public_code']];header('Location: eshop_assisted_sale_admin.php?saved=1',true,303);exit;
 }catch(Throwable $e){$error=$e instanceof PDOException?'Prodej se nepodařilo bezpečně uložit. Zkontrolujte objednávku před převzetím dalších peněz.':$e->getMessage();}
}
if(isset($_GET['new'])){$_SESSION['assisted_request']=['key'=>bin2hex(random_bytes(16)),'access'=>bin2hex(random_bytes(32))];unset($_SESSION['assisted_last_order']);}
$variants=$pdo->query("SELECT v.id,v.sku,v.amount_minor,v.attributes_json,pub.public_name FROM shop_variants v JOIN shop_products p ON p.id=v.product_id JOIN shop_product_publications pub ON pub.product_id=p.id WHERE p.offer_type='goods' AND p.catalog_status='active' AND pub.status='active' AND v.catalog_status='active' ORDER BY pub.public_name,v.sku")->fetchAll(PDO::FETCH_ASSOC);
$account=(int)($_GET['account_id']??$_POST['account_id']??0);$selected=(int)($_GET['variant_id']??$_POST['variant_id']??0);$quote=null;
if($selected>0){$variant=shopCheckoutLockVariant($pdo,$selected);if($variant)$quote=shopMemberPriceQuoteForVariant($pdo,$account,$variant);}
?>
