<?php if($quote):?><form method="post" class="card card-body"><?=csrf_field()?><input type="hidden" name="request_key" value="<?=assistedH($_SESSION['assisted_request']['key'])?>"><input type="hidden" name="variant_id" value="<?=$selected?>"><input type="hidden" name="account_id" value="<?=$account?>"><h2 class="h5">2. Kupující a převzetí</h2><p>Cena za kus: <strong><?=number_format($quote['effective_amount_minor']/100,2,',',' ')?> Kč</strong> <?=!empty($quote['is_member_price'])?'· doložená členská cena':'· veřejná cena'?></p><input type="hidden" name="expected_unit_minor" value="<?=(int)$quote['effective_amount_minor']?>"><label>Množství<input class="form-control" type="number" name="quantity" min="1" max="99" value="1" required></label>
<?php foreach(['first_name'=>'Jméno kupujícího','last_name'=>'Příjmení kupujícího','email'=>'E-mail kupujícího (volitelný při osobním prodeji)','payer_name'=>'Jméno plátce','recipient_name'=>'Jméno přebírajícího','reason'=>'Poznámka obsluhy'] as $name=>$label):?><label><?=assistedH($label)?><input class="form-control" name="<?=assistedH($name)?>" <?=$name!=='email'?'required':''?> maxlength="<?=$name==='email'?254:200?>" <?= $name==='email'?'type="email"':''?> value="<?=assistedH($_POST[$name]??'')?>"></label><?php endforeach;?><label>Sportovec jako příjemce (volitelné ID, vazba na účet musí být schválená)<input class="form-control" type="number" min="1" name="beneficiary_id"></label><label class="mt-2"><input type="checkbox" name="confirmed" value="1" required> Potvrzuji údaje, cenu a osobní převzetí. Platbu potvrdí hospodář samostatně.</label><button class="btn btn-primary mt-2">Uložit prodej a rezervaci</button></form><?php endif;?></main></body></html>
